1	import { Injectable } from '@angular/core';
2	import { HttpClient, HttpParams, HttpResponse } from '@angular/common/http';
3	import { Observable } from 'rxjs';
4	import { map } from 'rxjs/operators';
5	
6	import { ModelingSubmission } from 'app/entities/modeling-submission.model';
7	import { createRequestOption } from 'app/shared/util/request.util';
8	import { stringifyCircular } from 'app/shared/util/utils';
9	import { SubmissionService } from 'app/exercises/shared/submission/submission.service';
10	
11	export type EntityResponseType = HttpResponse<ModelingSubmission>;
12	
13	@Injectable({ providedIn: 'root' })
14	export class ModelingSubmissionService {
15	    public resourceUrl = 'api';
16	
17	    constructor(
18	        private http: HttpClient,
19	        private submissionService: SubmissionService,
20	    ) {}
21	
22	    /**
23	     * Create a new modeling submission
24	     * @param {ModelingSubmission} modelingSubmission - New submission to be created
25	     * @param {number} exerciseId - Id of the exercise, for which the submission is made
26	     */
27	    create(modelingSubmission: ModelingSubmission, exerciseId: number): Observable<EntityResponseType> {
28	        const copy = this.submissionService.convert(modelingSubmission);
29	        return this.http
30	            .post<ModelingSubmission>(`api/exercises/${exerciseId}/modeling-submissions`, stringifyCircular(copy), {
31	                headers: { 'Content-Type': 'application/json' }, // needed due to stringifyCircular
32	                observe: 'response',
33	            })
34	            .pipe(map((res: EntityResponseType) => this.submissionService.convertResponse(res)));
35	    }
36	
37	    /**
38	     * Update an existing modeling submission
39	     * @param {ModelingSubmission} modelingSubmission - Updated submission
40	     * @param {number} exerciseId - Id of the exercise, for which the submission is made
41	     */
42	    update(modelingSubmission: ModelingSubmission, exerciseId: number): Observable<EntityResponseType> {
43	        const copy = this.submissionService.convert(modelingSubmission);
44	        return this.http
45	            .put<ModelingSubmission>(`api/exercises/${exerciseId}/modeling-submissions`, stringifyCircular(copy), {
46	                headers: { 'Content-Type': 'application/json' }, // needed due to stringifyCircular
47	                observe: 'response',
48	            })
49	            .pipe(map((res: EntityResponseType) => this.submissionService.convertResponse(res)));
50	    }
51	
52	    /**
53	     * Get all submissions for an exercise
54	     * @param {number} exerciseId - Id of the exercise
55	     * @param {any?} req - Request option
56	     * @param correctionRound correctionRound for which to get the Submissions
57	     */
58	    getSubmissions(exerciseId: number, req?: any, correctionRound = 0): Observable<HttpResponse<ModelingSubmission[]>> {
59	        const url = `${this.resourceUrl}/exercises/${exerciseId}/modeling-submissions`;
60	        let params = createRequestOption(req);
61	        if (correctionRound !== 0) {
62	            params = params.set('correction-round', correctionRound.toString());
63	        }
64	        return this.http
65	            .get<ModelingSubmission[]>(url, {
66	                params,
67	                observe: 'response',
68	            })
69	            .pipe(map((res: HttpResponse<ModelingSubmission[]>) => this.submissionService.convertArrayResponse(res)));
70	    }
71	
72	    /**
73	     * Get an unassessed modeling exercise for an exercise
74	     * @param {number} exerciseId - Id of the exercise
75	     * @param {boolean?} lock - True if assessment is locked
76	     * @param correctionRound correctionRound for which to get the Submissions
77	     */
78	    getSubmissionWithoutAssessment(exerciseId: number, lock?: boolean, correctionRound = 0): Observable<ModelingSubmission | undefined> {
79	        const url = `api/exercises/${exerciseId}/modeling-submission-without-assessment`;
80	        let params = new HttpParams();
81	        if (correctionRound !== 0) {
82	            params = params.set('correction-round', correctionRound.toString());
83	        }
84	        if (lock) {
85	            params = params.set('lock', 'true');
86	        }
87	        return this.http.get<ModelingSubmission | undefined>(url, { params }).pipe(
88	            map((res?: ModelingSubmission) => {
89	                if (!res) {
90	                    return undefined;
91	                }
92	                return this.submissionService.convertSubmissionFromServer(res);
93	            }),
94	        );
95	    }
96	
97	    /**
98	     * Get a submission with given Id
99	     * @param {number} submissionId - Id of the submission
100	     * @param correctionRound
101	     * @param resultId
102	     */
103	    getSubmission(submissionId: number, correctionRound = 0, resultId?: number): Observable<ModelingSubmission> {
104	        const url = `api/modeling-submissions/${submissionId}`;
105	        let params = new HttpParams();
106	        if (correctionRound !== 0) {
107	            params = params.set('correction-round', correctionRound.toString());
108	        }
109	        if (resultId && resultId > 0) {
110	            params = params.set('resultId', resultId.toString());
111	        }
112	        return this.http.get<ModelingSubmission>(url, { params }).pipe(map((res: ModelingSubmission) => this.submissionService.convertSubmissionFromServer(res)));
113	    }
114	
115	    /**
116	     * Get a submission with given Id without locking it on artemis so plagiarism detection doesn't disrupt assessment
117	     * @param {number} submissionId - Id of the submission
118	     */
119	    getSubmissionWithoutLock(submissionId: number): Observable<ModelingSubmission> {
120	        const url = `api/modeling-submissions/${submissionId}`;
121	        let params = new HttpParams();
122	        params = params.set('withoutResults', 'true');
123	        return this.http.get<ModelingSubmission>(url, { params }).pipe(map((res: ModelingSubmission) => this.submissionService.convertSubmissionFromServer(res)));
124	    }
125	
126	    /**
127	     * Get the latest submission for a given participation
128	     * @param {number} participationId - Id of the participation
129	     */
130	    getLatestSubmissionForModelingEditor(participationId: number): Observable<ModelingSubmission> {
131	        return this.http
132	            .get<ModelingSubmission>(`api/participations/${participationId}/latest-modeling-submission`, { responseType: 'json' })
133	            .pipe(map((res: ModelingSubmission) => this.submissionService.convertSubmissionFromServer(res)));
134	    }
135	}
